questions.tests:
remotes = ["origin", "upstream"]
branches = ["main", "dev", "release/2.0"]
for r in remotes:
    for b in branches:
        for cmd in (f"git push --force {r} {b}", f"git push {r} {b} --force", f"git push -f {r} {b}",
                    f"git push -fu {r} {b}", f"git push --force-with-lease --force {r} {b}"):
            assert blocks_force_push(cmd), f"should block: {cmd}"
        for cmd in (f"git push --force-with-lease {r} {b}", f"git push {r} {b}", f"git push -u {r} {b}",
                    f"git push --follow-tags {r} {b}", f"git pull --force {r} {b}", f"git fetch -f {r}",
                    f"git push --force-with-lease --force-if-includes {r} {b}"):
            assert not blocks_force_push(cmd), f"should run: {cmd}"
assert not blocks_force_push("git status")
assert not blocks_force_push("ls -f")
